insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$maracai$q$, $q$https://www.maracai.sp.gov.br/portal/leis_decretos/11723/ (Lei 1.409/2003) ; https://www.maracai.sp.gov.br/portal/leis_decretos/11739/ (Lei 1.425/2004) ; https://www.maracai.sp.gov.br/portal/leis_decretos/12770/ (Lei 1.842/2012, revogada) ; https://www.maracai.sp.gov.br/portal/leis_decretos/18069/ (Lei 2.930/2026)$q$, $q$Atos oficiais de Maracaí: domínio público (Lei 9.610/1998 art. 8º IV). Geometria: OpenStreetMap (ODbL 1.0, © colaboradores do OSM).$q$, 8, $q$Lei 1.409/2003: proibida a entrada de caminhões e máquinas agrícolas na Av. São Paulo, salvo carga e descarga por até 1 h (24 h, toda a via). Lei 1.425/2004 (caminhões canavieiros na Rua José Gonçalves de Mendonça) desativada por alvo definido pela carga; Lei 1.842/2012 (cana no perímetro urbano) revogada pela Lei 2.930/2026.$q$);
